// The generated-file convention, shared by metrics #6, #20 and #25.
//
// Manifest: `scripts/generate/README.md`. Every markdown table row whose first two cells each hold a
// backticked repo-relative path is a row `{ generated, generator }`; a `generated` path ending in `/` names
// a directory of generated files. Header text: `Generated by <generator path>; do not edit.` within a
// file's first three lines (provenance may follow the period).

import { basename, isBinaryFile, isDataPath, isStructureGate } from "./lib.mjs";

export const MANIFEST = "scripts/generate/README.md";

/** Marker text in a file's first lines that says it is generated. */
const MARKER = /generated by|@generated|do not edit/i;
const HEADER = /Generated by (\S+?);\s*do not edit/i;
const MARKER_LINES = 5;
const HEADER_LINES = 3;

export function parseManifest(text) {
  const rows = [];
  const lines = text.split("\n");
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i].trim();
    if (!line.startsWith("|")) continue;
    const cells = line.replace(/^\||\|$/g, "").split("|");
    if (cells.length < 2) continue;
    const generated = /`([^`]+)`/.exec(cells[0])?.[1];
    const generator = /`([^`]+)`/.exec(cells[1])?.[1];
    if (generated && generator) rows.push({ generated, generator, line: i + 1 });
  }
  return rows;
}

export function manifestRows(repo) {
  return repo.has(MANIFEST) ? parseManifest(repo.text(MANIFEST)) : [];
}

export function isGeneratedName(path) {
  return basename(path).includes(".generated.");
}

/** Files whose tooling owns them: lockfiles carry "@generated" and changesets' boilerplate README. */
export function isToolOwned(path) {
  const base = basename(path);
  return base.endsWith(".lock") || base === "package-lock.json" || path === ".changeset/README.md";
}

function headLines(repo, path, count) {
  if (isBinaryFile(repo, path)) return [];
  const text = repo.text(path);
  const lines = [];
  let start = 0;
  while (lines.length < count && start <= text.length) {
    const end = text.indexOf("\n", start);
    lines.push(text.slice(start, end < 0 ? text.length : end));
    if (end < 0) break;
    start = end + 1;
  }
  return lines;
}

/** Whether the file's first lines say it is generated (outside data roots, tool-owned files and the gate). */
export function hasGeneratedMarker(repo, path) {
  if (isDataPath(path) || isToolOwned(path) || isStructureGate(path) || path === MANIFEST) return false;
  return headLines(repo, path, MARKER_LINES).some((line) => MARKER.test(line));
}

function header(repo, path) {
  const lines = headLines(repo, path, HEADER_LINES);
  for (let i = 0; i < lines.length; i += 1) {
    const match = HEADER.exec(lines[i]);
    if (match) return { generator: match[1].replace(/[.,;:)]+$/, ""), line: i + 1 };
  }
  return null;
}

/** The generator a file's header names, or null when it has no conforming header. */
export function headerGenerator(repo, path) {
  return header(repo, path)?.generator ?? null;
}

/** Where a generator lives: under `scripts/generate/`, or beside the recordings it writes in a data root. */
export function isGeneratorLocation(path) {
  return path.startsWith("scripts/generate/") || isDataPath(path);
}

/**
 * Every generator the convention names, `{ generator, path, line }`: each manifest row's (at the manifest
 * row) and each `Generated by` header of a generated file outside the data roots and this gate.
 */
export function namedGenerators(repo) {
  const named = manifestRows(repo).map((row) => ({ generator: row.generator, path: MANIFEST, line: row.line }));
  for (const path of repo.files) {
    if (isDataPath(path) || isStructureGate(path) || !isCommentable(repo, path)) continue;
    if (!isGeneratedName(path) && !hasGeneratedMarker(repo, path)) continue;
    const found = header(repo, path);
    if (found !== null) named.push({ generator: found.generator, path, line: found.line });
  }
  return named;
}

/** A file that can carry a comment header: not JSON, not binary (lib.mjs's `isBinaryFile`). */
export function isCommentable(repo, path) {
  return !path.endsWith(".json") && !isBinaryFile(repo, path);
}

/** The manifest row covering `path` (a file row or a directory row above it), or undefined. */
export function rowFor(rows, path) {
  return rows.find((row) => (row.generated.endsWith("/") ? path.startsWith(row.generated) : row.generated === path));
}
